P2=timerange('2014-01-01','2015-01-01');
names=fieldnames(IPR_tr);
c=contains(names,'A14');
N=names(c);
for i=1:length(N)
    IPR_tr.(N{i})(P1)= IPR_tr.(N{i})(P1)./1e3;
      IPR_tr.(N{i})(P2)= IPR_tr.(N{i})(P2)./1e3;
end
